package ru.neverland.townyjobs;
import com.palmergames.bukkit.towny.TownyCommandAddonAPI;import org.bukkit.configuration.file.YamlConfiguration;import org.bukkit.plugin.ServicePriority;import org.bukkit.plugin.java.JavaPlugin;import ru.neverland.townyjobs.api.TownyJobsApi;
public final class NeverLandTownyJobs extends JavaPlugin {
    private JobsService service;private WageService wages;private ru.neverland.townyjobs.mastery.MasteryService mastery;private CityBridge bridge;private boolean townCommand;
    @Override public void onEnable(){ try (var suiteGuard1 = ru.neverland.core.SuiteState.guard()) {
        if (!ru.neverland.core.ModuleLifecycle.begin(this)) return;
try{saveDefaultConfig();bridge=new CityBridge();var repo=new JobsRepository(getDataFolder().toPath().resolve("jobs-data.yml"));repo.load();service=new JobsService(this,repo,settings(),bridge);var menus=new JobsMenus(this,service);var command=new JobsCommand(this,service,menus);var direct=getCommand("townyjobs");if(direct==null)throw new IllegalStateException("Нет команды townyjobs");direct.setExecutor(command);direct.setTabCompleter(command);townCommand=TownyCommandAddonAPI.addSubCommand(TownyCommandAddonAPI.CommandType.TOWN,"jobs",command);if(!townCommand)getLogger().warning("/t jobs занят; доступна /townyjobs");getServer().getPluginManager().registerEvents(menus,this);getServer().getPluginManager().registerEvents(new JobsListener(service),this);getServer().getServicesManager().register(TownyJobsApi.class,service,this,ServicePriority.Normal);service.start();try{mastery=new ru.neverland.townyjobs.mastery.MasteryService(this,service);service.setMastery(mastery);ru.neverland.core.ModuleShutdown.register(this,mastery::prepareClose);}catch(Exception ex){getLogger().log(java.util.logging.Level.SEVERE,"Мастерские заказы приостановлены; обычные профессии сохранены",ex);}getCommand("jobpay").setExecutor((sender,cmd,label,args)->{sender.sendMessage(ru.neverland.core.EditableMessages.text(NeverLandTownyJobs.class, "Раздел заработка приостановлен: проверьте конфигурацию и журнал запуска."));return true;});try{wages=new WageService(this,service);}catch(Exception ex){if(mastery!=null)mastery.setProofsAvailable(false);getLogger().log(java.util.logging.Level.SEVERE,"Зарплаты приостановлены; профессии и опыт сохранены",ex);}if(service.fault())throw new IllegalStateException("Профессии не смогли рассчитать рабочие места");getLogger().info("Городские профессии включены: 7 профессий, рабочие места и опыт смен.");}catch(Exception|LinkageError ex){getLogger().log(java.util.logging.Level.SEVERE,"Профессии не загружены",ex);getServer().getPluginManager().disablePlugin(this);}} }
    private JobsSettings settings()throws Exception{var y=new YamlConfiguration();y.load(getDataFolder().toPath().resolve("config.yml").toFile());return JobsSettings.load(y,bridge.known());}
    public void reloadJobs()throws Exception{ try (var suiteGuard2 = ru.neverland.core.SuiteState.guard()) {var next=settings();service.reload(next);if(service.fault())throw new IllegalStateException("Настройки прочитаны, но рабочие места недоступны");} }
    public JobsService jobs(){ try (var suiteGuard3 = ru.neverland.core.SuiteState.guard()) {return service;} }
    @Override public void onDisable(){try{try (var suiteGuard4 = ru.neverland.core.SuiteState.guard()) {
        if (!ru.neverland.core.ModuleLifecycle.end(this)) return;
if(service!=null)service.stop();getServer().getServicesManager().unregisterAll(this);if(townCommand)TownyCommandAddonAPI.removeSubCommand(TownyCommandAddonAPI.CommandType.TOWN,"jobs");if(mastery!=null)mastery.prepareClose();}}finally{if(mastery!=null)mastery.awaitClosed();ru.neverland.core.ModuleShutdown.remove(this);}}
}
